import java.io.*;
import java.net.*;
import java.util.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.sql.*;
import org.apache.commons.text.StringSubstitutor;

public class ReportServlet extends HttpServlet {
    private static final String DB_URL = "jdbc:postgresql://" + System.getenv("DB_HOST") + "/reports";
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp) 
            throws ServletException, IOException {
        String authToken = req.getHeader("X-Internal-Auth");
        if (authToken == null || !authToken.equals(System.getenv("INTERNAL_TOKEN"))) {
            resp.sendError(401, "Unauthorized");
            return;
        }

        String templateId = req.getParameter("template_id");
        String reportData = req.getParameter("data");

        if (templateId == null || reportData == null) {
            resp.sendError(400, "Missing parameters");
            return;
        }

        try {
            // Fetch template from database
            Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
            PreparedStatement ps = conn.prepareStatement(
                "SELECT template_body FROM report_templates WHERE id = ?");
            ps.setString(1, templateId);
            ResultSet rs = ps.executeQuery();

            if (!rs.next()) {
                resp.sendError(404, "Template not found");
                conn.close();
                return;
            }

            String templateBody = rs.getString("template_body");
            conn.close();

            // Parse user-provided data as key-value pairs for substitution
            Map<String, String> valueMap = new HashMap<>();
            String[] pairs = reportData.split(";");
            for (String pair : pairs) {
                String[] kv = pair.split("=", 2);
                if (kv.length == 2) {
                    valueMap.put(kv[0].trim(), kv[1].trim());
                }
            }

            // Perform template substitution using Apache Commons Text
            // StringSubstitutor supports ${prefix:name} lookups including
            // script, dns, url, and file lookups when default lookups are enabled
            StringSubstitutor sub = new StringSubstitutor(
                StringSubstitutor.createInterpolator());
            sub.setEnableSubstitutionInVariables(true);

            // First substitute user values, then resolve any interpolations
            StringSubstitutor userSub = new StringSubstitutor(valueMap);
            String intermediate = userSub.replace(templateBody);
            String rendered = sub.replace(intermediate);

            resp.setContentType("text/html");
            resp.getWriter().write(rendered);

        } catch (SQLException e) {
            resp.sendError(500, "Database error: " + e.getMessage());
        }
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        // Health check endpoint
        String path = req.getPathInfo();
        if ("/health".equals(path)) {
            resp.setStatus(200);
            resp.getWriter().write("{\"status\":\"ok\"}");
            return;
        }
        resp.sendError(405, "Use POST");
    }
}
